using Ganss.Xss;using QuestPDF.Fluent;using QuestPDF.Helpers;using QuestPDF.Infrastructure;using System.Net;
namespace MyDoc.Services;public interface IPdfExportService{byte[]Create(string title,string html);}public sealed class PdfExportService(IHtmlSafetyService safety):IPdfExportService{public byte[]Create(string title,string html){QuestPDF.Settings.License=LicenseType.Community;var text=WebUtility.HtmlDecode(System.Text.RegularExpressions.Regex.Replace(safety.Sanitize(html),"<[^>]+>"," "));return Document.Create(c=>c.Page(p=>{p.Margin(48);p.Header().Text(title).FontSize(20).Bold();p.Content().PaddingTop(18).Text(text).FontSize(11);p.Footer().AlignCenter().Text(x=>{x.Span("DocSpace · ");x.CurrentPageNumber();});})).GeneratePdf();}}
